Standardized <- function(
    data,
    da,
    na,
    db,
    nb,
    sm = "dn") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("Standardized requires jmvcore to be installed (restart may be required)")

    if ( ! missing(da)) da <- jmvcore::resolveQuo(jmvcore::enquo(da))
    if ( ! missing(na)) na <- jmvcore::resolveQuo(jmvcore::enquo(na))
    if ( ! missing(db)) db <- jmvcore::resolveQuo(jmvcore::enquo(db))
    if ( ! missing(nb)) nb <- jmvcore::resolveQuo(jmvcore::enquo(nb))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(da), da, NULL),
            `if`( ! missing(na), na, NULL),
            `if`( ! missing(db), db, NULL),
            `if`( ! missing(nb), nb, NULL))


    options <- StandardizedOptions$new(
        da = da,
        na = na,
        db = db,
        nb = nb,
        sm = sm)

    analysis <- StandardizedClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

